import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Checks","description":"","frontmatter":{},"headers":[],"relativePath":"checks.md","filePath":"checks.md"}'),s={name:"checks.md"};function d(n,e,i,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h1><p><code>npm run audit</code> checks the components against the rules of kata. It has two parts: a reading of the sources, and a measurement of the examples in a browser. <code>npm run check</code> runs it with the other checks of the repository (<a href="https://github.com/sakuzu/kata/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING</a> lists them).</p><h2 id="the-sources" tabindex="-1">The sources <a class="header-anchor" href="#the-sources" aria-label="Permalink to &quot;The sources&quot;">​</a></h2><p><code>scripts/lint-components.mjs</code> reads the styles of the components in <code>src/svelte</code>.</p><ul><li>Spacing, type and colour take a token, never a raw length or colour.</li><li><code>padding</code> takes the pad scale and <code>gap</code> the gap scale.</li><li>Only the components that hold text in a control (Button, Toggle, TextInput and the other controls, a mark such as Badge, a list item, a pair or a table cell), at a container&#39;s edge (Text) or next to a line (Section, SectionHeader) trim text. The seat of a mark trims an empty line, and so does the summary of Prose, which seats its chevron.</li><li>No negative distance, no outer margin on a component&#39;s root (the layouts, Icon and Prose aside), no <code>@media</code> for a width and no <code>:has()</code> other than the next sibling.</li><li>Every custom property a component reads is defined.</li><li>Every component is exported, has an example and has a page here or in the <a href="./workbench/README">Workbench</a> chapter.</li></ul><h2 id="the-examples" tabindex="-1">The examples <a class="header-anchor" href="#the-examples" aria-label="Permalink to &quot;The examples&quot;">​</a></h2><p>The audit builds the examples and opens each one in Chromium, served by Vite&#39;s preview server. Every example is measured at three widths (1440, 768 and 390px), at the default and the largest text size, in the dark and the light theme, and with an English and a Japanese root. Every visible element inside the example is measured; a finding fails the audit.</p><table tabindex="0"><thead><tr><th>Rule</th><th>What is measured</th></tr></thead><tbody><tr><td>space</td><td>Padding and gaps are 0 or a step of the scale</td></tr><tr><td>margin</td><td>Outer margins appear only in Prose and Block, never negative</td></tr><tr><td>type</td><td>Font sizes are type roles; line heights are a step of the scale</td></tr><tr><td>border</td><td>Borders are 0, 1 or 2px and solid, so no border of the browser</td></tr><tr><td>height</td><td>An element with <code>data-h</code> has the height of that token</td></tr><tr><td>trim</td><td>Text is trimmed in a control, at a container&#39;s edge or at a line</td></tr><tr><td>trim-clip</td><td>Trimmed text keeps its vertical overflow, so no ink is cut</td></tr><tr><td>cursor</td><td>What can be pressed shows the pointer</td></tr><tr><td>contrast</td><td>Text reaches 7:1 on its surface (4.5:1 when disabled or dimmed)</td></tr><tr><td>focus-halo</td><td>A text field shows a 2px ring on focus</td></tr><tr><td>double-rule</td><td>No two lines run along one edge</td></tr><tr><td>double-inset</td><td>A container with padding never sits in another one</td></tr><tr><td>bundle-edge</td><td>Text in an unpadded container or surface keeps pad-md</td></tr><tr><td>inner-gap</td><td>In a padded container, neighbours are no further than the edge</td></tr><tr><td>box-touch</td><td>A control never touches the padded edge of its container</td></tr><tr><td>box-gap</td><td>Controls stacked vertically are at least md apart</td></tr><tr><td>rule-gap</td><td>A line is as far from what is above as from what is below</td></tr><tr><td>head-gap</td><td>A section header&#39;s head is pad-md from its content</td></tr><tr><td>head-near</td><td>A group&#39;s head is nearer its content than the group above</td></tr><tr><td>page-head-gap</td><td>A page&#39;s head is pad-lg from its content</td></tr><tr><td>section-head-gap</td><td>A section&#39;s head is gap-lg from its content</td></tr><tr><td>tabs-gap</td><td>Content under Tabs is gap-lg away (not in an unpadded container)</td></tr><tr><td>read-row</td><td>A list item that is only read has a line or a surface</td></tr><tr><td>first-line</td><td>A mark in a seat is centred on the ink of the first line</td></tr><tr><td>near</td><td>A control&#39;s description is nearer its label than the next one&#39;s</td></tr><tr><td>overlap</td><td>The children of a layout do not overlap</td></tr><tr><td>crush</td><td>Text is never squeezed narrower than two characters</td></tr><tr><td>fixed-frame</td><td>A Shell or an embedded root is not the frame of fixed elements</td></tr><tr><td>scroll-mark</td><td>A region that overflows shows a size-sm scrollbar on that axis</td></tr><tr><td>thumb</td><td>The thumb of that scrollbar reaches 3:1 on the region&#39;s surface</td></tr></tbody></table><p>Distances are measured from the edge of what is visible: the outline of a component with a line or a surface, a line, the inner edge of a container, or the ink of text. A line along one side of a component only is an edge on that side only; from the other side the distance runs to what is inside it (the text of tabs with a line along their bottom). An element marked <code>data-kata-skip</code> (drawn by the browser or by another library) is not measured.</p><p>head-gap allows two exceptions. Flush content under a head with an action keeps pad-md above it, so that the action that hangs below the head does not reach the first row, and its distance from the head may grow by that padding and the action&#39;s overhang. Flush content without an action keeps gap-xs above it, and its distance may grow by that gap. head-near allows the first group to lie further from its head by the action&#39;s overhang, and the second by the gap-xs.</p><p>first-line measures every seat (<a href="./measuring#a-mark-beside-text">a mark beside text</a>): an element whose <code>::before</code> is an empty line trimmed to its ink. The centre of the mark it holds is within 0.06px of the centre of the ink of the first line of the text beside it (the nearest sibling after it that holds text, else before it). The ink runs from the cap height to the baseline of the font, measured with a trimmed line placed before the text, and with a Japanese root it also takes the CJK ink above and below them, as a trimmed line does. The chevron of a Prose summary is drawn by the summary&#39;s own <code>::before</code> and is not measured, and neither is the end of a <a href="./components/text">Text</a> that has moved to a line of its own under the text (<code>data-under</code>).</p><p>scroll-mark measures every element that overflows on an axis with <code>overflow</code> auto or scroll (<a href="./layout#regions-that-scroll">Regions that scroll</a>): the box less its borders and its client size on that axis is the track&#39;s thickness, within 1.5px, as the client size is whole pixels and the scrollbar snaps to them. A hidden scrollbar measures 0. thumb composes <code>thumb</code> over the surface of the region and its ancestors, as contrast does for text. The audit runs Chromium without Playwright&#39;s hidden scrollbars, and hides only the page&#39;s own scrollbar, so that the three widths are the content&#39;s. The embed example puts kata under a root (<code>data-kata-root</code>) in a page that sets its own scrollbar colors, without the base CSS; the audit reads the tokens from the root of what it measures, so every check, scroll-mark included, measures the embed as it measures a page.</p><p>near measures a control with a description (a radio, a checkbox or a switch, which marks itself <code>data-control</code>) that another control follows: the distance from the ink of its label to the ink of its description is less than the distance from the ink of its last line to the ink of the next control&#39;s label.</p>',13)])])}const u=t(s,[["render",d]]);export{p as __pageData,u as default};
